                        (*sptr) &
                        ((*(sptr + wpls) << 1) | (*(sptr + wpls + 1) >> 31)) &
                        ((*(sptr + wpls2) << 2) | (*(sptr + wpls2 + 1) >> 30));
            }
        }
    }

}
